{"cards": [{"node_code": "N_eef038299b71d3a7", "definition": "研究铁路沿线及站场内各类建筑物（如站房、信号楼、机务段、仓库等）的规划、设计、构造、施工及维护的工程技术与理论。", "boundary": "本节点聚焦于铁路专用房屋建筑。边界在于区分“铁路房屋”与“线路工程”（路基、轨道等线性设施归线路工程）、“铁路房屋”与“通用土木工程”（非铁路专用的民用建筑归通用建筑类）。若内容涉及房屋内的通信信号设备安装，主挂载视主导内容而定，纯建筑结构归本节点。", "includes": ["铁路站房、生产办公用房、机务车辆段房屋的设计与构造", "铁路房屋的结构工程、建筑材料及施工养护技术", "铁路专用房屋的功能布局与防灾设计"], "excludes": ["铁路路基、轨道、道岔等线性线路设施（归入线路构造）", "铁路桥梁、隧道等跨越或地下结构（归入桥涵、隧道工程）", "非铁路专用的通用民用建筑设计"], "sibling_distinctions": [{"other_code": "N_123843572b56b5ce", "rule": "区分依据为设施形态：线路构造关注路基、轨道等线性基础设施；铁路房屋关注站房、仓库等点状或块状建筑物。"}, {"other_code": "N_3077dbf464f799b4", "rule": "区分依据为施工对象：线路施工侧重路基、轨道铺设；铁路房屋施工侧重建筑结构、装修及附属设施安装。"}], "cross_boundary_rule": "若内容涉及“站场房屋与线路接口”或“房屋基础与路基结合”，若侧重房屋本体结构，主挂载本节点；若侧重路基或轨道结构，主挂载线路构造或线路施工。"}, {"node_code": "N_ffb6718dd7daa49a", "definition": "研究既有铁路线路在运营过程中进行技术改造、能力扩建、标准提升及适应性改造的工程规划、设计与实施技术。", "boundary": "本节点聚焦于“既有线路”的改造与扩建。边界在于区分“旧线改造”与“新线建设”（新建线路归入线路规划、勘测与设计）、“旧线改造”与“养护维修”（日常维护归养护维修，结构性改造归本节点）。若改造涉及桥隧主体工程，主挂载视主导内容而定，纯线路平面纵断面调整归本节点。", "includes": ["既有铁路线路的增建二线、电气化改造、提速改造技术", "线路平面、纵断面调整及站场扩建工程", "旧线改造的可行性研究、设计方案及施工实施技术"], "excludes": ["新建铁路线路的规划、勘测与设计（归入线路规划、勘测与设计）", "线路日常养护、维修及病害整治（归入铁路养护与维修）", "铁路桥梁、隧道主体的新建或大修工程（归入桥涵、隧道工程）"], "sibling_distinctions": [{"other_code": "N_fa77cc328df13aee", "rule": "区分依据为项目性质：线路规划、勘测与设计针对新建线路；旧线改造及扩建针对既有线路的技术升级与能力扩展。"}, {"other_code": "N_9fd08c8551b14f8c", "rule": "区分依据为工程规模与目的：养护维修侧重保持线路原有状态与功能；旧线改造及扩建侧重改变线路技术标准、增加能力或改变线路走向。"}], "cross_boundary_rule": "若内容涉及“改造中的桥隧工程”或“改造中的信号系统升级”，若侧重线路整体改造方案与线路本体调整，主挂载本节点；若侧重特定桥隧结构或信号设备技术，主挂载对应专业节点。"}]}
